	// identifier is the team's name, used for routing alerts and identifying the
	// team in a uniform, machine-friendly format (for example, for Opsgenie
	// routing). It must be all lowercase alphanumeric with dashes, and must not
	// contain spaces - see ObservableOwner.validate.
	identifier       string
	handbookSlug     string
	handbookTeamName string
}

