	if strings.Contains(o.identifier, " ") || strings.ToLower(o.identifier) != o.identifier {
		return errors.Errorf("ObservableOwner identifier must be all lowercase with no spaces; found \"%s\"", o.identifier)
	}
	return nil
}

func (o *ObservableOwner) String() string {
	return o.identifier
}

